style.css:
@-moz-document domain("music.youtube.com") {
body, ytmusic-app {
    background: linear-gradient(to bottom right, #fdf6ec, #fbe9e7) !important;
    color: #4b2e2e !important;
    font-family: 'Georgia', serif !important;
  }

  /* Barra superior con textura de madera (simulada en color) */
  ytmusic-nav-bar, ytmusic-player-bar {
    background-color: #d8c3a5 !important;
    box-shadow: 0 2px 6px rgba(0,0,0,0.2);
    border-top: 2px solid #8b3a3a !important;
  }

  /* Botones con estilo burdeos */
  paper-icon-button, .ytmusic-icon-button {
    color: #8b3a3a !important;
    transition: color 0.3s ease;
  }

  paper-icon-button:hover, .ytmusic-icon-button:hover {
    color: #a64d4d !important;
  }

  /* Tarjetas de contenido con borde suave y fondo sepia */
  ytmusic-responsive-list-item-renderer,
  ytmusic-grid-renderer {
    background-color: #ece0d1 !important;
    color: #4b2e2e !important;
    border-radius: 8px;
    padding: 10px;
    margin-bottom: 12px;
    font-family: 'Courier New', monospace !important;
  }

  /* Enlaces y textos interactivos */
  a, .yt-simple-endpoint {
    color: #8b3a3a !important;
    text-decoration: none !important;
  }

  a:hover, .yt-simple-endpoint:hover {
    color: #a64d4d !important;
  }

  /* Scroll retro */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #8b3a3a;
    border-radius: 4px;
  }

  /* Oculta publicidad */
  ytmusic-guide-entry-renderer[has-ad] {
    display: none !important;
  }
}
